import{_ as t,o,c as a,a2 as i}from"./chunks/framework.mrTIYZc5.js";const p=JSON.parse('{"title":"Core Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concepts.md","filePath":"guide/concepts.md"}'),r={name:"guide/concepts.md"};function s(n,e,c,l,h,d){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h1><p>DSO is built on a few fundamental architectural pillars that ensure secrets are managed securely and predictably in Docker environments.</p><hr><h2 id="_1-the-secret-lifecycle" tabindex="-1">1. The Secret Lifecycle <a class="header-anchor" href="#_1-the-secret-lifecycle" aria-label="Permalink to &quot;1. The Secret Lifecycle&quot;">​</a></h2><p>DSO manages the entire lifecycle of a secret from the moment it is requested to the moment it is rotated or the container is destroyed.</p><ol><li><strong>Resolution</strong>: DSO identifies the secret in the external vault (AWS, Azure, Vault) and authenticates using the host&#39;s machine identity.</li><li><strong>Acquisition</strong>: The secret is fetched over a secure TLS connection and held exclusively in the <code>dso-agent</code> process memory.</li><li><strong>Injection</strong>: The secret is &quot;pushed&quot; into the target container. Unlike standard Docker secrets or environment variables, DSO can update these values <em>without</em> a container restart.</li><li><strong>Observation</strong>: The Watcher Engine monitors for &quot;Secret Drift&quot; (changes in the vault) or container lifecycle events.</li><li><strong>Reconciliation</strong>: If a drift is detected, the system automatically triggers a rotation to bring the container&#39;s state back in sync with the vault.</li></ol><hr><h2 id="_2-zero-persistence-philosophy" tabindex="-1">2. Zero-Persistence Philosophy <a class="header-anchor" href="#_2-zero-persistence-philosophy" aria-label="Permalink to &quot;2. Zero-Persistence Philosophy&quot;">​</a></h2><p>Security in DSO is rooted in the principle of <strong>Transient Secrets</strong>.</p><ul><li><strong>No Host Disk Access</strong>: Secrets never touch the host&#39;s physical storage (HDD/SSD). They are streamed directly from the agent&#39;s memory into the container&#39;s RAM.</li><li><strong>In-Memory Cache</strong>: The <code>dso-agent</code> maintains a thread-safe, in-process cache. This cache is purged immediately when the agent stops.</li><li><strong>RAMfs Mounts</strong>: Injected files are stored in <code>tmpfs</code> mounts within the container, ensuring they disappear if the container is compromised or restarted.</li></ul><hr><h2 id="_3-the-reconciliation-loop" tabindex="-1">3. The Reconciliation Loop <a class="header-anchor" href="#_3-the-reconciliation-loop" aria-label="Permalink to &quot;3. The Reconciliation Loop&quot;">​</a></h2><p>DSO operates as a <strong>State Reconciler</strong>. It treats your <code>dso.yaml</code> and the external Vault as the &quot;Desired State&quot; and the running containers as the &quot;Actual State.&quot;</p><p>The system continuously works to minimize the &quot;Reconciliation Gap&quot;:</p><ul><li><strong>Passive Reconcile</strong>: Polling the vault for updates.</li><li><strong>Active Reconcile</strong>: Responding to container start/restart events to ensure they always boot with the latest credentials.</li></ul><hr><h2 id="_4-atomic-injection-mechanisms" tabindex="-1">4. Atomic Injection Mechanisms <a class="header-anchor" href="#_4-atomic-injection-mechanisms" aria-label="Permalink to &quot;4. Atomic Injection Mechanisms&quot;">​</a></h2><p>To prevent &quot;Partial Secret Reads&quot; (where an app reads a half-updated config file), DSO uses atomic injection:</p><ul><li><strong>Tar Streaming</strong>: We stream a complete directory of secrets as a single TAR archive. Docker&#39;s extraction process is atomic at the file level.</li><li><strong>SIGHUP Reloads</strong>: For applications that support it, DSO sends a signal (e.g., <code>SIGHUP</code>) only <em>after</em> the entire secret payload has been successfully updated on the filesystem.</li></ul><hr><h2 id="_5-metadata-driven-orchestration" tabindex="-1">5. Metadata-Driven Orchestration <a class="header-anchor" href="#_5-metadata-driven-orchestration" aria-label="Permalink to &quot;5. Metadata-Driven Orchestration&quot;">​</a></h2><p>DSO relies on Docker Object Metadata (Labels) to discover its targets. This allows for &quot;Zero-Config&quot; scaling.</p><ul><li><strong><code>dso.reloader=true</code></strong>: Tells DSO that this container should be managed.</li><li><strong><code>dso.strategy=rolling</code></strong>: Defines how the container should be updated.</li><li><strong><code>dso.signal=SIGHUP</code></strong>: Specifies the reload signal for the application.</li></ul><p>By using labels, you can deploy new services that are &quot;DSO-Aware&quot; without ever updating the central DSO configuration.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><strong><a href="/docs/guide/architecture.html">System Architecture</a></strong>: Deep dive into the internal engines.</li><li><strong><a href="/docs/guide/security.html">Security Model</a></strong>: Understand the threat landscape.</li><li><strong><a href="/docs/guide/production-readiness.html">Production Readiness</a></strong>: How to deploy at scale. In-Memory Cache</li></ul><p>The agent maintains a thread-safe in-memory cache of all fetched secrets. This serves two purposes:</p><ol><li><strong>Performance</strong> — avoids hitting the cloud API on every container start</li><li><strong>Resilience</strong> — if the cloud provider is temporarily unavailable, the agent serves from cache</li></ol><p>Cache TTL is controlled by <code>agent.refresh_interval</code> in <code>dso.yaml</code>.</p>',29)])])}const g=t(r,[["render",s]]);export{p as __pageData,g as default};
